import {DEFAULT_RULES,REQUIRED,validateEvents,parseCSV,analyze,metrics,csvExport} from './engine.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(x),pct=x=>x===null?'N/A':`${Math.round(x*100)}%`,num=x=>x.toLocaleString();
let events=[],accounts=[],view='overview',selected=null,rules={...DEFAULT_RULES},page=0,queueMode='alerts',timelineMode='all',dataset='Included synthetic dataset',datasetKey='demo',notes={};
try{notes=JSON.parse(localStorage.getItem('ato-investigator-notes')||'{}');if(!notes||Array.isArray(notes)||typeof notes!=='object')notes={};}catch{notes={};}
const home=a=>a.events.find(e=>e.event_type==='login_success')?.country||a.events[0].country;
function filtered(){const from=$('#from-date').value,to=$('#to-date').value,country=$('#country').value,search=$('#search').value.toLowerCase().trim();return accounts.filter(a=>(country==='all'||home(a)===country)&&a.id.toLowerCase().includes(search)&&a.events.some(e=>(!from||e._time>=Date.parse(from+'T00:00:00Z'))&&(!to||e._time<Date.parse(to+'T00:00:00Z')+86400000)));}
function download(name,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function metric(label,value,hint,cls=''){return `<div class="metric"><div class="label">${label}</div><div class="value ${cls}">${value}</div><small>${hint}</small></div>`;}
function rowNote(a){return notes[datasetKey+'|'+a.id]?.status||'Not reviewed';}
function queue(list){const show=queueMode==='all'?list:list.filter(a=>a.alert),start=page*10,visible=show.slice(start,start+10);return `<div class="card"><div class="card-head"><div><h2>Account review queue</h2><p class="sub">Prioritized by the highest event score in account history.</p></div><div class="row-actions"><select id="queue-mode" aria-label="Queue scope"><option value="alerts" ${queueMode==='alerts'?'selected':''}>Alerted accounts</option><option value="all" ${queueMode==='all'?'selected':''}>All accounts</option></select><span class="badge">${show.length} accounts</span></div></div>${!show.length?'<div class="empty">No accounts match. Adjust the filters or detection threshold.</div>':`<div class="table-wrap"><table><thead><tr><th>ACCOUNT</th><th>SCORE</th><th>PRIORITY</th><th>SIGNALS OBSERVED</th><th>FLAGGED TRANSFER VALUE</th><th>REVIEW STATUS</th><th></th></tr></thead><tbody>${visible.map(a=>`<tr><td><button class="account-link" data-account="${esc(a.id)}">${esc(a.id)}</button><div class="event-meta">${esc(home(a))} · ${a.events.length} events</div></td><td class="score">${a.score}<span class="event-meta"> / 100</span></td><td><span class="badge ${a.severity}">${a.severity}</span></td><td class="reason-text">${esc(a.reasons.join(' · ')||'No rule signals')}</td><td>${money(a.exposure)}</td><td>${esc(rowNote(a))}</td><td><button class="button secondary" data-account="${esc(a.id)}">Investigate ↗</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Showing ${start+1}–${Math.min(start+10,show.length)} of ${show.length}</span><div class="row-actions"><button id="prev-page" class="button secondary" ${page===0?'disabled':''}>Previous</button><button id="next-page" class="button secondary" ${start+10>=show.length?'disabled':''}>Next</button></div></div>`}</div>`;}
function trend(list){
  const days=new Map();const from=$('#from-date').value,to=$('#to-date').value;
  for(const a of list)for(const e of a.events){const day=new Date(e._time).toISOString().slice(0,10);if((from&&day<from)||(to&&day>to))continue;if(!days.has(day))days.set(day,{all:0,flag:0});days.get(day).all++;if(e.eventScore>=rules.alertThreshold)days.get(day).flag++;}
  const rows=[...days].sort(([a],[b])=>a.localeCompare(b));if(!rows.length)return '<div class="empty">No events in this date window.</div>';
  const max=Math.max(1,...rows.map(([,v])=>v.all)),w=600,h=150,bar=Math.min(28,440/rows.length),gap=540/rows.length;
  return `<svg class="chart" viewBox="0 0 600 190" role="img" aria-label="Daily event counts and flagged events in selected dates">${[0,.5,1].map(f=>`<line x1="35" x2="590" y1="${h-f*130}" y2="${h-f*130}" stroke="#edf1f3"/><text x="1" y="${h-f*130+4}">${Math.round(max*f)}</text>`).join('')}${rows.map(([d,v],i)=>{const x=45+i*gap;return `<rect x="${x}" y="${h-v.all/max*130}" width="${bar}" height="${v.all/max*130}" rx="3" fill="#d3e8e4"><title>${d}: ${v.all} total events</title></rect><rect x="${x}" y="${h-v.flag/max*130}" width="${bar}" height="${v.flag/max*130}" rx="2" fill="#087f75"><title>${v.flag} flagged events</title></rect>${rows.length<=15||i%Math.ceil(rows.length/10)===0?`<text x="${x+bar/2}" y="175" text-anchor="middle">${d.slice(5)}</text>`:''}`;}).join('')}</svg><div class="legend"><span><i style="background:#d3e8e4"></i>All activity</span><span><i style="background:#087f75"></i>Flagged events</span></div>`;
}
function overview(list){const m=metrics(list);const reasons=new Map();for(const a of list.filter(a=>a.alert))for(const reason of a.reasons)reasons.set(reason,(reasons.get(reason)||0)+1);const counts=[...reasons].sort((a,b)=>b[1]-a[1]).slice(0,5);return `<div class="metrics">${metric('Accounts in scope',num(list.length),'Accounts selected by global filters')}${metric('Accounts needing review',num(m.alerts),`Score ≥ ${rules.alertThreshold} · ${(list.length?m.alerts/list.length*100:0).toFixed(1)}% of accounts`,'danger')}${metric('Flagged transfer value',money(m.exposure),'Rule-flagged transfers · full history','accent')}${metric('Detection recall',pct(m.recall),`${m.tp} caught / ${m.tp+m.fn} labeled takeovers`)}</div><div class="grid-two"><div class="card"><div class="card-head"><h2>Activity over time</h2><span class="badge">UTC · selected dates</span></div><p class="sub">A view of account activity and events meeting the alert threshold.</p>${trend(list)}</div><div class="card"><h2>Signals across alerted accounts</h2><p class="sub">An account can have more than one signal.</p>${counts.length?counts.map(([r,c])=>`<div class="bar-row"><div class="bar-top"><span>${esc(r)}</span><strong>${c}</strong></div><div class="track"><div class="fill" style="width:${c/Math.max(1,m.alerts)*100}%"></div></div></div>`).join(''):'<div class="empty">No alerted accounts in scope.</div>'}</div></div>${queue(list)}`;}
function investigation(list){if(!selected)return `<div class="banner">Select an account to connect login activity, credential changes, and transfers into an investigation timeline.</div>${queue(list)}`;const a=list.find(x=>x.id===selected);if(!a)return '<div class="empty">The selected account is outside the filters. Reset filters or select another account.</div>';const note=notes[datasetKey+'|'+a.id]||{},show=a.events.filter(e=>timelineMode==='all'||e.reasons.length),last=show.slice(-100);return `<button class="back" id="back-queue">← Back to account queue</button><div class="detail-head"><div><h2>${esc(a.id)} <span class="badge ${a.severity}">${a.severity} priority</span></h2><span class="sub">Home country ${esc(home(a))} · ${a.events.length} events · all available history</span></div><button class="button secondary" id="export-account">Download timeline ↓</button></div><div class="metrics">${metric('Account score',a.score,'Highest event score · not a probability',a.alert?'danger':'')}${metric('Signals observed',a.reasons.length,'Distinct detection reasons')}${metric('Total transfers',money(a.totalTransferred),'All transfers in account history')}${metric('Flagged transfer value',money(a.exposure),'Transfer events meeting alert threshold','accent')}</div><div class="detail-grid"><div class="card"><div class="card-head"><h2>Account activity timeline</h2><select id="timeline-mode" aria-label="Timeline display"><option value="all" ${timelineMode==='all'?'selected':''}>All activity</option><option value="signals" ${timelineMode==='signals'?'selected':''}>Signals only</option></select></div><p class="sub">Chronological sequence · UTC · ${show.length>100?'latest 100 of ':''}${show.length} events</p><div class="timeline-scroll">${last.length?last.map(e=>`<div class="timeline-event"><time>${new Date(e._time).toISOString().slice(5,10)}<br>${new Date(e._time).toISOString().slice(11,16)} UTC</time><div><div class="event-title"><span class="event-dot ${e.reasons.length?'flag':''}"></span>${esc(e.event_type.replaceAll('_',' '))}${e.event_type==='transfer'?' · '+money(e.amount):''}</div><div class="event-meta">${esc(e.device_id)} · ${esc(e.country)} · ${esc(e.ip_address)}${e.beneficiary_id?'<br>Beneficiary '+esc(e.beneficiary_id):''}</div>${e.reasons.length?`<div class="event-reasons">${esc(e.reasons.join(' · '))} <strong> · score ${e.eventScore}</strong></div>`:''}</div></div>`).join(''):'<div class="empty">No signal events for this account.</div>'}</div></div><div><div class="card"><h2>Investigation evidence</h2><p class="sub">Rule-generated observations from recorded activity.</p><ul class="findings">${a.reasons.length?a.reasons.map(r=>`<li>${esc(r)}</li>`).join(''):'<li>No configured detection rules matched.</li>'}</ul><div class="banner warning">A rule match is a reason to investigate. Travel, a new phone, or a password recovery can also trigger signals.</div><details><summary>Reveal synthetic ground truth</summary><p class="method">${a.label===null?'No evaluation label available.':a.label===1?'Labeled takeover account':'Labeled legitimate account'}<br>${esc(a.events[0].scenario||'No scenario supplied')}<br>Labels describe the account, not individual event ownership, and are excluded from scoring.</p></details></div><div class="card section-gap"><h2>Case notes</h2><p class="sub">Stored in this browser, scoped to the dataset. Notes are not sent to a server.</p><label>Review outcome<select id="case-status">${['Not reviewed','Investigating','Escalated','Benign activity'].map(s=>`<option ${note.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="section-gap">Investigator notes<textarea id="case-note" placeholder="Record evidence, alternative explanations, and follow-up steps.">${esc(note.text||'')}</textarea></label><div class="note-save"><button class="button" id="save-note">Save case notes</button><button class="button secondary" id="export-notes">Export notes</button></div><p id="note-result" role="status" class="sub"></p></div></div></div>`;}
function rulesView(list){const m=metrics(list),base=metrics(analyze(events,DEFAULT_RULES).filter(a=>list.some(x=>x.id===a.id)));const controls=[['failedCount','Failed login count',1,8,1,'Failures before a successful login within the lookback window.'],['windowMinutes','Login lookback window',5,120,5,'Minutes for failed login and password reset context.'],['transferAmount','Large transfer threshold',100,7000,100,'USD amount used by transfer rules.'],['followupMinutes','Transfer follow-up window',10,180,10,'Minutes after a suspicious login or beneficiary addition.'],['alertThreshold','Account alert threshold',20,90,5,'Accounts alert when their maximum event score reaches this value.']];return `<div class="banner">Experiment with rule settings and observe account-level detection results. These are illustrative rules; scores are not calibrated probabilities.</div><div class="rule-grid"><div class="card"><div class="card-head"><h2>Detection settings</h2><button id="reset-rules" class="button secondary">Restore defaults</button></div>${controls.map(([id,label,min,max,step,hint])=>`<div class="rule-control"><label for="rule-${id}">${label}<output id="output-${id}">${id==='transferAmount'?money(rules[id]):rules[id]}</output></label><input id="rule-${id}" data-rule="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${rules[id]}"><small>${hint}</small></div>`).join('')}</div><div><div class="card"><div class="card-head"><h2>Detection outcomes</h2><span class="badge">Account level</span></div><p class="sub">${m.labeled} labeled accounts in scope. Missing labels are excluded from precision and recall.</p><div class="matrix"><div><strong>${m.tp}</strong>Takeovers caught</div><div class="bad"><strong>${m.fp}</strong>Legitimate accounts flagged</div><div class="bad"><strong>${m.fn}</strong>Takeovers missed</div><div><strong>${m.tn}</strong>Legitimate accounts unflagged</div></div><div class="legend"><span>Precision <strong>${pct(m.precision)}</strong></span><span>Recall <strong>${pct(m.recall)}</strong></span><span>Alerts <strong>${m.alerts}</strong></span></div><table class="compare"><thead><tr><th>METRIC</th><th>DEFAULT RULES</th><th>CURRENT RULES</th></tr></thead><tbody>${[['Accounts alerted',base.alerts,m.alerts],['Precision',pct(base.precision),pct(m.precision)],['Recall',pct(base.recall),pct(m.recall)],['Flagged transfer value',money(base.exposure),money(m.exposure)]].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="card section-gap"><h2>How scoring works</h2><p class="method">At a successful login: new device <strong>+20</strong>, new country <strong>+20</strong>, recent failed login burst <strong>+25</strong>, recent password reset <strong>+15</strong>.<br><br>At a transfer: large transfer after a suspicious login on the same device <strong>+45</strong>; large transfer to a newly added beneficiary <strong>+35</strong>. Scores on the same event add together. The account score is its highest event score, capped at 100.<br><br>The first successful login establishes the initial device and country baseline. All rule context uses earlier events; equal-time events are ordered by event ID.</p></div></div></div>`;}
function dataView(){return `<div class="grid-two"><div class="card"><h2>Bring your own activity CSV</h2><p class="method">Start with the included fictional dataset, or upload a CSV using the schema below. Uploads are analyzed locally and are not transmitted to the hosted site.</p><div class="data-actions"><label class="button file-label">Upload CSV<input type="file" id="upload" accept=".csv,text/csv"></label><button class="button secondary" id="download-data">Download current CSV</button><button class="button secondary" id="restore-demo">Restore demo data</button></div><p class="sub">Limit: 10 MB and 50,000 events. Transfer amounts are interpreted as USD.</p><div class="table-wrap"><table><thead><tr><th>COLUMN</th><th>MEANING</th></tr></thead><tbody>${[['event_id','Unique event identifier'],['account_id','Fictional or approved account identifier'],['timestamp','ISO 8601 with timezone, e.g. 2026-10-11T10:00:00Z'],['event_type','login_success, login_failed, password_reset, beneficiary_added, transfer'],['device_id','Device identifier for the event'],['country','Country at event time'],['ip_address','IP address or masked identifier'],['amount','Nonnegative USD amount; zero for non-transfer events'],['beneficiary_id','Required for transfer and beneficiary_added; blank otherwise'],['is_ato','Optional account label: 0 or 1, consistent across account'],['scenario','Optional description for the evaluation reveal']].map(([a,b])=>`<tr><td><code>${a}</code></td><td class="reason-text">${b}</td></tr>`).join('')}</tbody></table></div></div><div><div class="card"><h2>About the demo dataset</h2><p class="method">Reproducibly generated with Python standard library and random seed 42. It contains 80 fictional accounts with activity from October 1–11, 2026 UTC.</p><ul class="doc-list"><li>8 takeovers with a strong activity sequence</li><li>4 takeovers with limited observable signals</li><li>8 legitimate accounts traveling abroad</li><li>6 legitimate password recovery sequences</li><li>6 legitimate new phone logins</li><li>48 accounts with routine activity</li></ul><p class="method">IP addresses use the documentation range 192.0.2.0/24. Account labels represent scenario truth across the whole account history, including benign activity before the takeover.</p></div><div class="card section-gap"><h2>Interpretation and limitations</h2><ul class="doc-list"><li>Flagged transfer value is review exposure, not confirmed fraud loss.</li><li>Precision and recall use account labels and full account history.</li><li>The date filter selects accounts; it does not truncate rule context. Only the trend chart is restricted to selected dates.</li><li>Country is a first-login cohort filter. It is not an IP geolocation or travel-speed calculation.</li><li>Rules miss low-signal attacks and can flag legitimate changes.</li><li>The app does not block transfers, contact customers, or use a trained model.</li><li>Case notes remain in the current browser and can be exported as JSON.</li></ul></div></div></div>`;}
function render(){
  const list=filtered();const datesInvalid=$('#from-date').value&&$('#to-date').value&&$('#from-date').value>$('#to-date').value;
  $('#content').innerHTML=datesInvalid?'<div class="empty">From date must be on or before through date.</div>':view==='overview'?overview(list):view==='investigate'?investigation(list):view==='rules'?rulesView(list):dataView();
  $('#page-title').textContent={overview:'Investigation overview',investigate:'Account investigations',rules:'Detection playground',data:'Data & methodology'}[view];
  $('.nav.active')?.classList.remove('active');$(`[data-view="${view}"]`)?.classList.add('active');
  $('#dataset-info').textContent=`${dataset} · ${num(events.length)} events · ${accounts.length} accounts`;
  document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>{selected=b.dataset.account;view='investigate';timelineMode='signals';render();});
  $('#queue-mode')?.addEventListener('change',e=>{queueMode=e.target.value;page=0;render();});
  $('#prev-page')?.addEventListener('click',()=>{page--;render();});$('#next-page')?.addEventListener('click',()=>{page++;render();});
  $('#back-queue')?.addEventListener('click',()=>{selected=null;render();});
  $('#timeline-mode')?.addEventListener('change',e=>{timelineMode=e.target.value;render();});
  $('#export-account')?.addEventListener('click',()=>{const a=accounts.find(a=>a.id===selected);download('account-timeline.csv',csvExport(a.events.map(e=>({...e,reasons:e.reasons.join('; ')})),[...REQUIRED,'eventScore','reasons']));});
  $('#save-note')?.addEventListener('click',()=>{const next={...notes,[datasetKey+'|'+selected]:{status:$('#case-status').value,text:$('#case-note').value,updatedAt:new Date().toISOString()}};try{localStorage.setItem('ato-investigator-notes',JSON.stringify(next));notes=next;$('#note-result').textContent='Saved in this browser.';}catch{$('#note-result').textContent='Browser storage is unavailable. Export your notes instead.';notes=next;}});
  $('#export-notes')?.addEventListener('click',()=>{const pending={...notes,[datasetKey+'|'+selected]:{status:$('#case-status').value,text:$('#case-note').value,updatedAt:new Date().toISOString()}};download('case-notes.json',JSON.stringify(pending,null,2),'application/json');});
  document.querySelectorAll('[data-rule]').forEach(input=>{input.oninput=()=>{$('#output-'+input.dataset.rule).textContent=input.dataset.rule==='transferAmount'?money(Number(input.value)):input.value;};input.onchange=()=>{rules[input.dataset.rule]=Number(input.value);accounts=analyze(events,rules);const focus=input.id;render();$('#'+focus)?.focus();};});
  $('#reset-rules')?.addEventListener('click',()=>{rules={...DEFAULT_RULES};accounts=analyze(events,rules);render();});
  $('#download-data')?.addEventListener('click',()=>download('account-events.csv',csvExport(events,[...REQUIRED,'is_ato','scenario'])));
  $('#restore-demo')?.addEventListener('click',()=>loadDemo());
  $('#upload')?.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('File exceeds 10 MB.');const raw=await f.text(),validated=validateEvents(parseCSV(raw));let hash=2166136261;for(const c of raw)hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0;load(validated,`Uploaded: ${f.name}`,'upload-'+hash.toString(16));$('#error').hidden=true;}catch(error){$('#error').textContent=error.message;$('#error').hidden=false;}});
}
function load(rows,name,key){events=rows;accounts=analyze(events,rules);dataset=name;datasetKey=key;selected=null;page=0;$('#from-date').value='';$('#to-date').value='';$('#search').value='';$('#country').innerHTML='<option value="all">All countries</option>'+[...new Set(accounts.map(home))].sort().map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');render();}
async function loadDemo(){try{const response=await fetch('data/events.json');if(!response.ok)throw Error('Demo data could not be loaded.');load(validateEvents(await response.json()),'Included synthetic dataset','demo');$('#error').hidden=true;}catch(error){$('#error').textContent=error.message+' Run the app through the HTTP server documented in README.';$('#error').hidden=false;}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;page=0;render();});
for(const id of ['from-date','to-date','country','search'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=0;render();});
$('#reset-filters').onclick=()=>{for(const id of ['from-date','to-date','search'])$('#'+id).value='';$('#country').value='all';page=0;render();};
$('#export-alerts').onclick=()=>download('ato-alerts.csv',csvExport(filtered().filter(a=>a.alert).map(a=>({account_id:a.id,score:a.score,priority:a.severity,reasons:a.reasons.join('; '),flagged_transfer_value_usd:a.exposure,review_status:rowNote(a)})),['account_id','score','priority','reasons','flagged_transfer_value_usd','review_status']));
loadDemo();
